components.css:
.ds-current-glass{--canvas:#edf5ff;--surface:#fcfdff;--ink:#173250;--primary:#153ea8;--control:#6b8099;--rule:#b9cbe1;--tint:#eaf1fc;font-family:Manrope,sans-serif;color:var(--ink);background:#edf5ff;padding:20px;border-radius:26px;}.ds-current-glass label{display:block;font-size:14px;margin-bottom:8px;}.ds-current-glass input{font-family:inherit;font-size:16px;min-height:50px;width:100%;padding:13px 14px;border-radius:14px;margin-bottom:12px;}.ds-current-glass button{font-family:inherit;font-size:14px;font-weight:600;line-height:1.4;min-height:44px;padding:10px 24px;border-radius:999px;cursor:pointer;}.ds-current-glass details{margin-top:16px;}.ds-current-glass summary{min-height:44px;width:fit-content;}.ds-current-glass :is(button,input,summary):focus-visible{outline:3px solid var(--primary);outline-offset:3px;}.liquid-metal-button{font-family:Manrope,sans-serif;min-height:44px;font-size:14px;font-weight:600;line-height:1.4;border-radius:999px;padding:10px 18px;color:var(--primary,#153ea8);cursor:pointer;}.liquid-metal-button:focus-visible{outline:3px solid var(--primary,#153ea8);outline-offset:3px;}.primary-button{padding:10px 24px;}.liquid-metal-button { position:relative; isolation:isolate; overflow:hidden; background:linear-gradient(125deg,#fbfdff 4%,#9eafc4 28%,#eaf7ff 48%,#8da8c3 72%,#fff 96%); border:1px solid var(--control,#6b8099); box-shadow:inset 0 1px 0 #fff,0 3px 8px #29486b14; } .liquid-metal-button::before { content:""; position:absolute; inset:3px; z-index:-1; border-radius:inherit; background:linear-gradient(180deg,#fff 0%,#f4f9ff 42%,#dceafa 48%,#edf5fd 100%); box-shadow:inset 0 1px 0 #fff,inset 0 -5px 8px #7899bc26; pointer-events:none; } .liquid-material { position:absolute; inset:0; z-index:-3; pointer-events:none; border-radius:inherit; overflow:hidden; opacity:0; transition:opacity 180ms ease-out; } .liquid-metal-button[data-liquid-active] .liquid-material[data-ready] { opacity:1; transition-duration:240ms; } .liquid-material canvas { display:block; width:100%; height:100%; } .liquid-shimmer { position:absolute; inset:0; z-index:-2; border-radius:inherit; overflow:hidden; pointer-events:none; container-type:size; opacity:.7; } .liquid-shimmer-spark { position:absolute; inset:0 auto auto 0; height:100cqh; aspect-ratio:1; } .liquid-shimmer-spark::before { content:""; position:absolute; inset:-100%; background:conic-gradient(from 225deg,transparent 0deg,#fff 55deg,#c7e8ff 90deg,transparent 91deg); } .liquid-metal-button.primary-button { color:#fff; border-color:var(--primary,#153ea8); filter:none; } .liquid-metal-button.primary-button::before { background:linear-gradient(180deg,#315dc5 0%,#244fb9 42%,#153ea8 49%,#12358e 100%); box-shadow:inset 0 1px 0 #ffffff80,inset 0 -5px 8px #061d5433; } .liquid-metal-button.text-button { padding:10px 14px; border-radius:999px; text-decoration:none; } .problem .liquid-metal-button::before { background:var(--surface,#fcfdff); } .liquid-metal-button:is(.starter-button,.match-button) { border-radius:var(--row-radius,14px); padding-inline:14px; margin-block:5px; } .liquid-metal-button:is(.starter-button,.match-button)::before { inset:2px; } .liquid-ripple { position:absolute; z-index:1; border-radius:50%; pointer-events:none; background:radial-gradient(circle,#c4e7ff66,transparent 65%); transform:translate(-50%,-50%) scale(.02); animation:liquid-ripple 550ms cubic-bezier(.16,1,.3,1) forwards; } @keyframes liquid-ripple { to { transform:translate(-50%,-50%) scale(1); opacity:0; } } .liquid-metal-button:disabled { background:var(--rule,#b9cbe1); box-shadow:none; color:var(--muted,#465f7b); cursor:not-allowed; } .liquid-metal-button:disabled::before { background:var(--tint,#eaf1fc); box-shadow:none; } .liquid-metal-button:disabled .liquid-shimmer { display:none; } .liquid-metal-button:focus-visible { box-shadow:0 0 0 3px var(--canvas,#edf5ff); } @media (hover:hover) and (pointer:fine) { .liquid-metal-button:not(:disabled):hover .liquid-shimmer-spark { transform:translateX(calc(100cqw - 100%)); } .liquid-metal-button:not(:disabled):hover .liquid-shimmer-spark::before { transform:rotate(270deg); } } @media (prefers-reduced-motion:no-preference) { .liquid-shimmer-spark,.liquid-shimmer-spark::before { transition:transform 650ms cubic-bezier(.16,1,.3,1); } .liquid-metal-button { transition:transform 150ms cubic-bezier(.23,1,.32,1); } .liquid-metal-button:not(:disabled):active:not(:focus-visible) { transform:scale(.98); } } @media (prefers-reduced-motion:reduce) { .liquid-ripple { display:none; } } @media (prefers-reduced-transparency:reduce) { .liquid-metal-button { background:var(--surface,#fcfdff); box-shadow:none; } .liquid-material,.liquid-ripple,.liquid-shimmer { display:none; } } @media (forced-colors:active) { .liquid-metal-button,.liquid-metal-button.primary-button { background:ButtonFace; color:ButtonText; border:1px solid ButtonText; box-shadow:none; } .liquid-metal-button::before,.liquid-material,.liquid-ripple,.liquid-shimmer { display:none; } .liquid-metal-button:disabled { color:GrayText; border-color:GrayText; } } @media(prefers-reduced-motion:reduce){.liquid-metal-button,.liquid-metal-button *,.liquid-metal-button::before,.liquid-metal-button *::before{transition:none!important;animation:none!important;}}.glass-filter { position:absolute; width:0; height:0; pointer-events:none; overflow:hidden; }
.app-surface :is(button,a,input[type=search],select,summary) {
  --glass-x:50%; --glass-y:20%;
  -webkit-backdrop-filter:blur(10px) saturate(140%);
  backdrop-filter:blur(10px) saturate(140%);
}
.app-surface :is(input[type=search],select,summary,.app-header a,.app-footer a,.about-index a,.skip-link) {
  background-color:#f3f9ffb8;
  background-image:radial-gradient(100px circle at var(--glass-x) var(--glass-y),#ffffffb3,transparent 75%),linear-gradient(135deg,#ffffff70,#b8dbf02b 55%,#fff8);
  border:1px solid var(--control);
  box-shadow:inset 0 1px 0 #fff,inset 0 -1px 0 #88b0d94d,0 4px 12px #28476714;
}
.app-surface :is(summary,.app-footer a,.about-index a) { border-radius:12px; padding:10px 12px; }
.app-surface .brand { border-radius:16px; padding:6px 10px; }
.app-surface .app-header a[aria-current] { background-color:#153ea8; background-image:radial-gradient(80px circle at var(--glass-x) var(--glass-y),#fff2,transparent 80%); border-color:#153ea8; }
.app-surface :is(.app-header,.shell-body,.about-index) { background-color:#f3f9ffe6; -webkit-backdrop-filter:blur(14px) saturate(130%); backdrop-filter:blur(14px) saturate(130%); }
.app-surface .preview-bar { background:#eff7ffcc; backdrop-filter:blur(14px); }
.app-surface .proto-picker { background:#d5e5f3c7; border-color:#8da8c3; backdrop-filter:blur(12px); }
.app-surface .proto-picker-item { color:#173250; }
.app-surface .proto-picker-highlight { background:linear-gradient(135deg,#fff9,#b6d4ee88); box-shadow:inset 0 1px 0 #fff,0 3px 10px #28476722; }
.app-surface .liquid-metal-button { background:linear-gradient(125deg,#ffffffaa,#adcee480 45%,#fff9); }
.app-surface .liquid-metal-button::before { background:linear-gradient(180deg,#ffffff9c,#f0f8ffc9 42%,#dceafa80 49%,#edf5fdb3); }
.app-surface .liquid-metal-button.primary-button::before { background:linear-gradient(180deg,#315dc5f5,#153ea8f5 49%,#12358ef5); }
.glass-effect { position:absolute; inset:2px; z-index:-1; border-radius:inherit; overflow:hidden; pointer-events:none; }
.glass-distortion,.glass-tint,.glass-shine { position:absolute; inset:0; border-radius:inherit; pointer-events:none; }
.glass-distortion { backdrop-filter:blur(3px) saturate(140%); }
.glass-tint { background:#ffffff14; }
.glass-shine { background:radial-gradient(100px circle at var(--glass-x) var(--glass-y),#ffffff80,transparent 70%); box-shadow:inset 1px 1px 1px #ffffffb3,inset -1px -1px 1px #c6e7ff80; opacity:.45; }
.primary-button .glass-tint { background:transparent; }
.primary-button .glass-shine { opacity:.08; }
.app-surface [data-glass-active] .glass-distortion { filter:url('#liquid-glass-distortion'); }
.app-surface [data-glass-active] .glass-shine { opacity:.7; }
.app-surface .primary-button[data-glass-active] .glass-shine { opacity:.1; }
.app-surface :is(input[type=search],select):focus-visible { background-color:#f7fbffe6; }
.app-surface .liquid-metal-button:disabled { background:var(--rule); box-shadow:none; }
.app-surface .liquid-metal-button:disabled::before { background:var(--tint); }
.liquid-metal-button:disabled .glass-effect { display:none; }
@media(prefers-reduced-motion:no-preference) {
  .glass-shine { transition:opacity 220ms cubic-bezier(.16,1,.3,1); }
  .app-surface :is(input[type=search],select,summary,.app-header a,.app-footer a,.about-index a) { transition:background-color 180ms ease-out,box-shadow 180ms ease-out; }
}
@media(prefers-reduced-motion:reduce) { .glass-distortion { filter:none!important; } }
@media(prefers-reduced-transparency:reduce) {
  .glass-effect { display:none; }
  .app-surface :is(button,a,input[type=search],select,summary,.app-header,.shell-body,.about-index,.preview-bar,.proto-picker) { -webkit-backdrop-filter:none!important; backdrop-filter:none!important; background-image:none; background-color:var(--surface,#fcfdff); }
  .app-surface .liquid-metal-button::before { background:var(--surface); }
  .app-surface .liquid-metal-button.primary-button::before,.app-surface .app-header a[aria-current] { background:var(--primary); }
}
@media(forced-colors:active) {
  .glass-effect { display:none; }
  .app-surface :is(button,a,input[type=search],select,summary,.app-header,.shell-body,.about-index,.preview-bar,.proto-picker) { -webkit-backdrop-filter:none!important; backdrop-filter:none!important; background:Canvas; color:CanvasText; border-color:ButtonText; box-shadow:none; }
  .app-surface .liquid-metal-button::before { display:none; }
  .app-surface .liquid-metal-button:disabled { color:GrayText; border-color:GrayText; }
}
